"""Regression tests for the shared certified-consensus authentication.

The plain (:func:`locate_cert_evidence`) and weighted
(:func:`locate_weighted_cert_evidence`) evidence paths share one
implementation of certificate verification, observation verification and
query-binding checks. These tests run entirely through the public entry
points and pin the evidence bytes captured before that unification, so any
behaviour drift — in encoding, authentication or either tally — fails here.
"""

import hashlib
import hmac
import json
import unittest

from nearproof import (
    BoundAttestedObservation,
    CertifiedConsensusEvidence,
    Consensus,
    ConsensusPolicy,
    RangeDecision,
    VerifierTrust,
    WeightedCertifiedConsensusEvidence,
    WeightedConsensus,
    attest_observation_for_point,
    audit_cert_evidence,
    audit_weighted_cert_evidence,
    cert,
    locate_cert,
    locate_cert_evidence,
    locate_weighted_cert_evidence,
    revoke_trust,
)

ROOT = b"\x09" * 32
OTHER_ROOT = b"\x08" * 32
KEYS = {"a": b"\xaa" * 32, "b": b"\xbb" * 32, "c": b"\xcc" * 32, "d": b"\xdd" * 32}
POSITIONS = {"a": (3.0, 0.0), "b": (0.0, 4.0), "c": (0.0, 0.0), "d": (50.0, 50.0)}

POINT = (0.0, 0.0)
CONTEXT = "room-7"

# Evidence bytes captured from the public entry points before the shared
# authentication helpers were introduced; the refactor must reproduce them
# byte for byte for the same legal inputs.
GOLDEN = {
    "plain_accepted": (
        ""
    ),
    "plain_rejected": (
        ""
    ),
    "plain_four": (
        ""
    ),
    "weighted_accepted": (
        ""
    ),
    "weighted_rejected": (
        ""
    ),
    "weighted_single": (
        ""
    ),
    "weighted_heavy": (
        ""
    ),
}


def decision(upper_bound=5.0, *, accepted=True):
    return RangeDecision(
        sample_count=1, upper_bound=upper_bound, accepted=accepted
    )


def trust(ident):
    x, y = POSITIONS[ident]
    return cert(ident, x, y, KEYS[ident], ROOT)


def record(ident, upper_bound=5.0, *, accepted=True):
    x, y = POSITIONS[ident]
    return attest_observation_for_point(
        ident, x, y, decision(upper_bound, accepted=accepted),
        POINT, CONTEXT, 0.0, KEYS[ident],
    )


def triangle_records(upper_bound=5.0, **kwargs):
    return [
        record("a", upper_bound, **kwargs),
        record("b", upper_bound, **kwargs),
        record("c", upper_bound, **kwargs),
    ]


def triangle_trusts():
    return [trust("a"), trust("b"), trust("c")]


def low_records():
    # Upper bound 1.0 covers only the verifier at the origin.
    return triangle_records(upper_bound=1.0)


def golden_bytes(name):
    return bytes.fromhex(GOLDEN[name])


def plain_policy():
    return ConsensusPolicy({"a": 2, "b": 1, "c": 1}, 3)


def heavy_policy():
    return ConsensusPolicy({"a": 1, "b": 1, "c": 5}, 5)


def resign_plain(body_list):
    body = json.dumps(body_list, separators=(",", ":")).encode()
    mac = hmac.new(ROOT, b"NPCCE1" + body, hashlib.sha256).digest()
    return json.dumps(
        {"version": 1, "body": body.hex(), "mac": mac.hex()},
        separators=(",", ":"),
    ).encode()


def plain_body(name="plain_accepted"):
    outer = json.loads(golden_bytes(name))
    return json.loads(bytes.fromhex(outer["body"]))


class GoldenEvidenceBytesTest(unittest.TestCase):
    """Legal inputs must reproduce the pre-refactor evidence byte for byte."""

    def test_plain_evidence_bytes_are_stable(self):
        evidence = locate_cert_evidence(
            triangle_records(), POINT, CONTEXT, triangle_trusts(), ROOT
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("plain_accepted"))

    def test_plain_rejected_evidence_bytes_are_stable(self):
        evidence = locate_cert_evidence(
            low_records(), POINT, CONTEXT, triangle_trusts(), ROOT
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("plain_rejected"))

    def test_plain_four_verifier_evidence_bytes_are_stable(self):
        records = triangle_records() + [record("d")]
        trusts = triangle_trusts() + [trust("d")]
        evidence = locate_cert_evidence(records, POINT, CONTEXT, trusts, ROOT)
        self.assertEqual(evidence.to_bytes(), golden_bytes("plain_four"))

    def test_weighted_evidence_bytes_are_stable(self):
        evidence = locate_weighted_cert_evidence(
            triangle_records(), triangle_trusts(), POINT, CONTEXT,
            plain_policy(), ROOT,
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("weighted_accepted"))

    def test_weighted_rejected_evidence_bytes_are_stable(self):
        evidence = locate_weighted_cert_evidence(
            low_records(), triangle_trusts(), POINT, CONTEXT,
            plain_policy(), ROOT,
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("weighted_rejected"))

    def test_weighted_single_verifier_evidence_bytes_are_stable(self):
        evidence = locate_weighted_cert_evidence(
            [record("c")], [trust("c")], POINT, CONTEXT,
            ConsensusPolicy({"c": 1}, 1), ROOT,
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("weighted_single"))

    def test_weighted_heavy_evidence_bytes_are_stable(self):
        evidence = locate_weighted_cert_evidence(
            low_records(), triangle_trusts(), POINT, CONTEXT,
            heavy_policy(), ROOT,
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("weighted_heavy"))

    def test_permuted_inputs_give_identical_bytes(self):
        records = triangle_records()
        trusts = triangle_trusts()
        evidence = locate_cert_evidence(
            [records[2], records[0], records[1]], POINT, CONTEXT,
            [trusts[1], trusts[2], trusts[0]], ROOT,
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("plain_accepted"))
        weighted = locate_weighted_cert_evidence(
            [records[2], records[0], records[1]],
            [trusts[1], trusts[2], trusts[0]],
            POINT, CONTEXT, plain_policy(), ROOT,
        )
        self.assertEqual(weighted.to_bytes(), golden_bytes("weighted_accepted"))

    def test_mixed_objects_and_bytes_give_identical_bytes(self):
        records = triangle_records()
        trusts = triangle_trusts()
        mixed_records = [records[0].to_bytes(), records[1], records[2].to_bytes()]
        mixed_trusts = [trusts[0], trusts[1].to_bytes(), trusts[2]]
        evidence = locate_cert_evidence(
            mixed_records, POINT, CONTEXT, mixed_trusts, ROOT
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("plain_accepted"))
        weighted = locate_weighted_cert_evidence(
            mixed_records, mixed_trusts, POINT, CONTEXT, plain_policy(), ROOT,
        )
        self.assertEqual(weighted.to_bytes(), golden_bytes("weighted_accepted"))

    def test_one_shot_iterables_give_identical_bytes(self):
        evidence = locate_cert_evidence(
            (r for r in triangle_records()), POINT, CONTEXT,
            (t for t in triangle_trusts()), ROOT,
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("plain_accepted"))
        weighted = locate_weighted_cert_evidence(
            (r for r in triangle_records()), (t for t in triangle_trusts()),
            POINT, CONTEXT, plain_policy(), ROOT,
        )
        self.assertEqual(weighted.to_bytes(), golden_bytes("weighted_accepted"))

    def test_extra_unused_trust_is_not_frozen_into_evidence(self):
        # An extra valid certificate may be supplied but is not written into
        # the evidence, which carries only the participating items.
        trusts = triangle_trusts() + [trust("d")]
        evidence = locate_cert_evidence(
            triangle_records(), POINT, CONTEXT, trusts, ROOT
        )
        self.assertEqual(evidence.to_bytes(), golden_bytes("plain_accepted"))
        weighted = locate_weighted_cert_evidence(
            triangle_records(), trusts, POINT, CONTEXT, plain_policy(), ROOT,
        )
        self.assertEqual(weighted.to_bytes(), golden_bytes("weighted_accepted"))

    def test_existing_evidence_still_deserializes_and_audits(self):
        for name in (
            "plain_accepted", "plain_rejected", "plain_four",
        ):
            blob = golden_bytes(name)
            evidence = CertifiedConsensusEvidence.from_bytes(blob)
            self.assertEqual(evidence.to_bytes(), blob)
            rerun = audit_cert_evidence(blob, ROOT)
            self.assertEqual(rerun, audit_cert_evidence(evidence, ROOT))
            self.assertIsInstance(rerun, Consensus)
        for name in (
            "weighted_accepted", "weighted_rejected",
            "weighted_single", "weighted_heavy",
        ):
            blob = golden_bytes(name)
            evidence = WeightedCertifiedConsensusEvidence.from_bytes(blob)
            self.assertEqual(evidence.to_bytes(), blob)
            rerun = audit_weighted_cert_evidence(blob, ROOT)
            self.assertEqual(rerun, audit_weighted_cert_evidence(evidence, ROOT))
            self.assertIsInstance(rerun, WeightedConsensus)

    def test_rejected_consensus_is_packaged_not_raised(self):
        # Falling short of the tally threshold geometrically is a result,
        # not an exception: the evidence is still produced and audits back.
        plain = audit_cert_evidence(golden_bytes("plain_rejected"), ROOT)
        self.assertEqual(
            plain, Consensus(total=3, support=1, rejected=("a", "b"),
                             accepted=False)
        )
        weighted = audit_weighted_cert_evidence(
            golden_bytes("weighted_rejected"), ROOT
        )
        self.assertEqual(
            weighted,
            WeightedConsensus(total_weight=4, support_weight=1,
                              rejected=("a", "b"), accepted=False),
        )


class AuthenticationFailureTest(unittest.TestCase):
    """Certificate, observation and binding failures on both paths."""

    def test_root_contract_on_every_entry_point(self):
        records = triangle_records()
        trusts = triangle_trusts()
        policy = plain_policy()
        for bad in (bytearray(ROOT), "", None, 0):
            with self.assertRaises(TypeError, msg=repr(bad)):
                locate_cert(records, POINT, CONTEXT, trusts, bad)
            with self.assertRaises(TypeError, msg=repr(bad)):
                locate_cert_evidence(records, POINT, CONTEXT, trusts, bad)
            with self.assertRaises(TypeError, msg=repr(bad)):
                locate_weighted_cert_evidence(
                    records, trusts, POINT, CONTEXT, policy, bad
                )
            with self.assertRaises(TypeError, msg=repr(bad)):
                audit_cert_evidence(golden_bytes("plain_accepted"), bad)
            with self.assertRaises(TypeError, msg=repr(bad)):
                audit_weighted_cert_evidence(
                    golden_bytes("weighted_accepted"), bad
                )
        with self.assertRaises(ValueError):
            locate_cert(records, POINT, CONTEXT, trusts, b"")
        with self.assertRaises(ValueError):
            locate_cert_evidence(records, POINT, CONTEXT, trusts, b"")
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                records, trusts, POINT, CONTEXT, policy, b""
            )
        with self.assertRaises(ValueError):
            audit_cert_evidence(golden_bytes("plain_accepted"), b"")
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence(
                golden_bytes("weighted_accepted"), b""
            )

    def test_wrong_root_rejected_on_both_paths(self):
        records = triangle_records()
        trusts = triangle_trusts()
        with self.assertRaises(ValueError):
            locate_cert(records, POINT, CONTEXT, trusts, OTHER_ROOT)
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                records, trusts, POINT, CONTEXT, plain_policy(), OTHER_ROOT
            )
        with self.assertRaises(ValueError):
            audit_cert_evidence(golden_bytes("plain_accepted"), OTHER_ROOT)
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence(
                golden_bytes("weighted_accepted"), OTHER_ROOT
            )

    def test_certificate_failures_match_on_both_paths(self):
        records = triangle_records()
        trusts = triangle_trusts()
        policy = plain_policy()
        # Missing certificate for one observation id.
        with self.assertRaises(ValueError):
            locate_cert(records, POINT, CONTEXT, trusts[:2], ROOT)
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                records, trusts[:2], POINT, CONTEXT, policy, ROOT
            )
        # Duplicated certificate id.
        with self.assertRaises(ValueError):
            locate_cert(records, POINT, CONTEXT, trusts + [trusts[0]], ROOT)
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                records, trusts + [trusts[0]], POINT, CONTEXT, policy, ROOT
            )
        # Tampered certificate MAC.
        forged = VerifierTrust.from_bytes(trusts[0].to_bytes())
        forged = forged.__class__(1, forged.id, forged.x, forged.y,
                                  forged.key, b"\x00" * 32)
        with self.assertRaises(ValueError):
            locate_cert(records, POINT, CONTEXT, [forged] + trusts[1:], ROOT)
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                records, [forged] + trusts[1:], POINT, CONTEXT, policy, ROOT
            )

    def test_observation_failures_match_on_both_paths(self):
        trusts = triangle_trusts()
        policy = plain_policy()
        # Record signed under the wrong key.
        records = triangle_records()
        x, y = POSITIONS["a"]
        wrong_key = attest_observation_for_point(
            "a", x, y, decision(), POINT, CONTEXT, 0.0, KEYS["b"]
        )
        with self.assertRaises(ValueError):
            locate_cert([wrong_key] + records[1:], POINT, CONTEXT, trusts, ROOT)
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                [wrong_key] + records[1:], trusts, POINT, CONTEXT, policy, ROOT
            )
        # Certificate coordinates disagree with the record.
        with self.assertRaises(ValueError):
            locate_cert(
                triangle_records(), POINT, CONTEXT,
                [cert("a", 9.0, 0.0, KEYS["a"], ROOT)] + trusts[1:], ROOT,
            )
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                triangle_records(),
                [cert("a", 9.0, 0.0, KEYS["a"], ROOT)] + trusts[1:],
                POINT, CONTEXT, policy, ROOT,
            )
        # Record not bound to the queried point or context.
        with self.assertRaises(ValueError):
            locate_cert(triangle_records(), (1.0, 0.0), CONTEXT, trusts, ROOT)
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                triangle_records(), trusts, (1.0, 0.0), CONTEXT, policy, ROOT
            )
        with self.assertRaises(ValueError):
            locate_cert(triangle_records(), POINT, "room-8", trusts, ROOT)
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                triangle_records(), trusts, POINT, "room-8", policy, ROOT
            )
        # Duplicated observation id.
        records = triangle_records()
        with self.assertRaises(ValueError):
            locate_cert(
                [records[0], records[0], records[1]], POINT, CONTEXT,
                trusts, ROOT,
            )
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                [records[0], records[0], records[1]], trusts,
                POINT, CONTEXT, policy, ROOT,
            )

    def test_resigned_outer_cannot_mask_inner_tampering(self):
        # An attacker holding the root swaps in a record signed under the
        # wrong key and re-signs the outer MAC: the rerun still rejects.
        body = plain_body()
        x, y = POSITIONS["a"]
        wrong_key = attest_observation_for_point(
            "a", x, y, decision(), POINT, CONTEXT, 0.0, KEYS["b"]
        )
        body[2][0] = wrong_key.to_bytes().hex()
        with self.assertRaises(ValueError):
            audit_cert_evidence(resign_plain(body), ROOT)

    def test_resigned_outer_cannot_mask_a_wrong_consensus(self):
        body = plain_body()
        body[4] = [3, 1, ["a", "b"], False]
        with self.assertRaises(ValueError):
            audit_cert_evidence(resign_plain(body), ROOT)

    def test_tampered_outer_mac_rejected(self):
        for blob, audit in (
            (golden_bytes("plain_accepted"), audit_cert_evidence),
            (golden_bytes("weighted_accepted"), audit_weighted_cert_evidence),
        ):
            outer = json.loads(blob)
            outer["mac"] = "00" * 32
            forged = json.dumps(outer, separators=(",", ":")).encode()
            with self.assertRaises(ValueError):
                audit(forged, ROOT)

    def test_weight_set_must_match_record_ids(self):
        records = triangle_records()
        trusts = triangle_trusts()
        for weights in ({"a": 1, "b": 1}, {"a": 1, "b": 1, "c": 1, "d": 1},
                        {"a": 1, "b": 1, "z": 1}):
            policy = ConsensusPolicy(weights, 1)
            with self.assertRaises(ValueError, msg=repr(weights)):
                locate_weighted_cert_evidence(
                    records, trusts, POINT, CONTEXT, policy, ROOT
                )


class TallyDifferenceTest(unittest.TestCase):
    """The two tally methods keep their distinct public behaviour."""

    def test_plain_path_needs_three_and_uses_a_fixed_quorum_of_three(self):
        trusts = triangle_trusts()
        with self.assertRaises(ValueError):
            locate_cert(
                triangle_records()[:2], POINT, CONTEXT, trusts[:2], ROOT
            )
        with self.assertRaises(ValueError):
            locate_cert_evidence(
                triangle_records()[:2], POINT, CONTEXT, trusts[:2], ROOT
            )
        # Four verifiers, one too far away: exactly three support.
        records = triangle_records() + [record("d")]
        consensus = locate_cert(
            records, POINT, CONTEXT, trusts + [trust("d")], ROOT
        )
        self.assertEqual(consensus.support, 3)
        self.assertEqual(consensus.rejected, ("d",))
        self.assertTrue(consensus.accepted)

    def test_weighted_path_allows_a_single_verifier(self):
        consensus = audit_weighted_cert_evidence(
            golden_bytes("weighted_single"), ROOT
        )
        self.assertEqual(
            consensus,
            WeightedConsensus(total_weight=1, support_weight=1,
                              rejected=(), accepted=True),
        )
        # The plain path rejects the same single-observation input.
        with self.assertRaises(ValueError):
            locate_cert([record("c")], POINT, CONTEXT, [trust("c")], ROOT)

    def test_weights_decide_where_the_count_quorum_fails(self):
        # Same records: only the origin verifier covers the point. The
        # plain tally rejects (support 1 < 3) while the weighted tally
        # accepts because that verifier carries weight 5 of 7 >= 5.
        plain = audit_cert_evidence(golden_bytes("plain_rejected"), ROOT)
        self.assertFalse(plain.accepted)
        weighted = audit_weighted_cert_evidence(
            golden_bytes("weighted_heavy"), ROOT
        )
        self.assertEqual(weighted.support_weight, 5)
        self.assertEqual(weighted.total_weight, 7)
        self.assertTrue(weighted.accepted)

    def test_closed_disk_boundary_counts_as_support_on_both_paths(self):
        # Verifier a sits exactly 3.0 away from the point; a bound of 3.0
        # is the closed boundary and supports, while b at 4.0 does not.
        records = triangle_records(upper_bound=3.0)
        trusts = triangle_trusts()
        consensus = locate_cert(records, POINT, CONTEXT, trusts, ROOT)
        self.assertEqual(consensus.support, 2)
        self.assertEqual(consensus.rejected, ("b",))
        weighted = locate_weighted_cert_evidence(
            records, trusts, POINT, CONTEXT, plain_policy(), ROOT
        )
        weighted_result = audit_weighted_cert_evidence(weighted, ROOT)
        self.assertEqual(weighted_result.support_weight, 3)
        self.assertEqual(weighted_result.rejected, ("b",))

    def test_decision_accepted_flag_is_ignored_on_both_paths(self):
        records = triangle_records(accepted=False)
        trusts = triangle_trusts()
        consensus = locate_cert(records, POINT, CONTEXT, trusts, ROOT)
        self.assertEqual(consensus.support, 3)
        self.assertTrue(consensus.accepted)
        weighted = locate_weighted_cert_evidence(
            records, trusts, POINT, CONTEXT, plain_policy(), ROOT
        )
        self.assertEqual(
            audit_weighted_cert_evidence(weighted, ROOT).support_weight, 4
        )

    def test_rejected_ids_are_lexicographic_regardless_of_input_order(self):
        records = low_records()
        trusts = triangle_trusts()
        shuffled = locate_cert(
            [records[1], records[2], records[0]], POINT, CONTEXT,
            [trusts[2], trusts[0], trusts[1]], ROOT,
        )
        self.assertEqual(shuffled.rejected, ("a", "b"))
        weighted = locate_weighted_cert_evidence(
            [records[1], records[2], records[0]],
            [trusts[2], trusts[0], trusts[1]],
            POINT, CONTEXT, plain_policy(), ROOT,
        )
        self.assertEqual(
            audit_weighted_cert_evidence(weighted, ROOT).rejected, ("a", "b")
        )

    def test_revocation_rules_are_unchanged(self):
        records = triangle_records()
        trusts = triangle_trusts()
        # A hit permanently revokes the certificate.
        revocation = revoke_trust(trusts[0], ROOT)
        with self.assertRaises(ValueError):
            locate_cert(
                records, POINT, CONTEXT, trusts, ROOT,
                revocations=[revocation],
            )
        # A revocation that hits no certificate the records use is itself
        # a contract breach.
        unrelated = revoke_trust(trust("d"), ROOT)
        with self.assertRaises(ValueError):
            locate_cert(
                records, POINT, CONTEXT, trusts, ROOT,
                revocations=[unrelated],
            )
        # An empty revocation iterable changes nothing.
        consensus = locate_cert(
            records, POINT, CONTEXT, trusts, ROOT, revocations=[]
        )
        self.assertTrue(consensus.accepted)

    def test_caller_inputs_are_not_mutated(self):
        records = triangle_records()
        trusts = triangle_trusts()
        record_snapshot = list(records)
        trust_snapshot = list(trusts)
        policy = plain_policy()
        locate_cert(records, POINT, CONTEXT, trusts, ROOT)
        locate_cert_evidence(records, POINT, CONTEXT, trusts, ROOT)
        locate_weighted_cert_evidence(
            records, trusts, POINT, CONTEXT, policy, ROOT
        )
        audit_cert_evidence(golden_bytes("plain_accepted"), ROOT)
        audit_weighted_cert_evidence(golden_bytes("weighted_accepted"), ROOT)
        self.assertEqual(records, record_snapshot)
        self.assertEqual(trusts, trust_snapshot)
        self.assertEqual(dict(policy.weights), {"a": 2, "b": 1, "c": 1})
        self.assertEqual(policy.threshold, 3)


if __name__ == "__main__":
    unittest.main()
